% def n_symmetrization_of (X : C) : C := n_union X (n_inverse X)
% def n_irreflexive (X Y : C) : Prop := n_subclass (n_restrict X Y Y) (n_complement n_identity_relation)
% def n_connected (X Y : C) : Prop :=
%   n_subclass (n_cross_product Y Y) (n_union n_identity_relation (n_symmetrization_of X))
% def n_transitive (R Y : C) : Prop :=
%   n_subclass (n_compose (n_restrict R Y Y) (n_restrict R Y Y)) (n_restrict R Y Y)
% def n_asymmetric (R Y : C) : Prop := n_restrict (n_intersection R (n_inverse R)) Y Y = n_null_class
% def n_segment (R Y W : C) : C := n_domain_of (n_restrict R Y (n_singleton W))
% /-- `U` is a nonempty subclass of `Y` without an `R`-minimal element -/
% def noMin (R Y U : C) : Prop := U ⊆ Y ∧ U.Nonempty ∧ ∀ a ∈ U, ∃ v ∈ U, op v a ∈ R
% def n_well_ordering (R Y : C) : Prop := n_connected R Y ∧ ¬ ∃ U, noMin R Y U
% def n_least (R U : C) : C := if h : ∃ a ∈ U, ∀ v ∈ U, op v a ∉ R then S (Classical.choose h) else ∅
% def n_not_well_ordering (R Y : C) : C := if h : ∃ U, noMin R Y U then Classical.choose h else ∅
% def n_section (R Y W : C) : Prop := n_subclass Y W ∧ n_subclass (n_domain_of (n_restrict R W Y)) Y
% /-- von Neumann ordinals: transitive sets well-ordered by membership -/
% def isOrd (a : Z) : Prop := n_well_ordering n_element_relation (S a) ∧ n_subclass (n_sum_class (S a)) (S a)
% def n_ordinal_numbers : C := {a | isOrd a}
% def n_kind_1_ordinals : C := n_union (n_singleton n_null_class) (n_image n_successor_relation n_ordinal_numbers)
% def n_limit_ordinals : C := n_intersection (n_complement n_kind_1_ordinals) n_ordinal_numbers
% /-- rest_of(x) ' u = x restricted to u, only where that restriction is a set (the fixed rest_of4) -/
% def n_rest_of (X : C) : C :=
%   {c | ∃ u r, c = op u r ∧ u ∈ n_domain_of X ∧ S r = n_restrict X (S u) n_universal_class}
% def n_rest_relation : C := {c | ∃ x r, c = op x r ∧ S r = n_rest_of (S x)}
% def n_recursion_equation_functions (W : C) : C :=
%   {x | n_function W ∧ n_function (S x) ∧ n_member (n_domain_of (S x)) n_ordinal_numbers ∧
%     n_compose W (n_rest_of (S x)) = S x}
% def n_union_of_range_map : C := {c | ∃ x y, c = op x y ∧ n_sum_class (n_range_of (S x)) = S y}
% def n_recursion (_ _ _ : C) : C := ∅
% def n_add_relation : C := ∅
% def n_ordinal_add (X Y : C) : C := n_apply (n_recursion X n_successor_relation n_union_of_range_map) Y
% def n_ordinal_multiply (X _ : C) : C := n_recursion n_null_class (n_apply n_add_relation X) n_union_of_range_map
% def n_integer_of (X : C) : C := if n_member X n_omega then X else n_null_class
